bilities", "status": "current", "indicators": "two deaf interns", "themes": {"cross_cultural": {"kind": "connecting_communities", "criterion": "level 2: specific current program for people with disabilities, limited reach (single property)"}}}, {"id": "E7", "activity": "Founding donor to Nareit Foundation grant program supporting nonprofits that increase participation of underrepresented populations in the REIT industry", "quote": "Host is a Founding Donor of Nareit Foundation’s DTD Giving Campaign and Grant Program, which supports nonprofit organizations working to increase the participation of underrepresented populations in the REIT and publicly traded real estate industry.", "source_doc": "sustainability_report", "section": "Inclusion Across the Value Chain > Build Capacity Within the Real Estate Industry", "status": "current", "indicators": "none disclosed", "themes": {"cross_cultural": {"kind": "connecting_communities", "criterion": "level 2: specific current activity, no reach figures"}}}, {"id": "E8", "activity": "Procurement practice seeking to increase capital expenditure spend with historically underrepresented or overlooked suppliers", "quote": "To develop a more resilient and expanded supplier base, Host proactively seeks opportunities to increase direct capital expenditure spend with historically underrepresented or overlooked suppliers, contractors and consultants.", "source_doc": "sustainability_report", "section": "Inclusion Across the Value Chain > Create Economic Opportunity Within Supplier Base", "status": "current", "indicators": "none disclosed", "themes": {"cross_cultural": {"kind": "internal_practice", "criterion": "level 2: specific current practice, no figures"}}}, {"id": "E9", "activity": "Support for the Marriott-Sorenson Center for Hospitality Leadership at Howard University (an HBCU), including employee engagement with students on careers", "quote": "In 2025, Host employees shared real estate investing perspectives at a Center event and